--------------------------------------------------------------------------
-- FIXTURE (constructed, not organic)
-- Platform  : DB2 for z/OS, native SQL procedure
-- Tables    : CLAIM, CLAIM_PAYMENT, CUSTOMER_HOLD, CUSTOMER_RISK, CLAIM_AUDIT
-- Assumed DDL context (matters for effect closure):
--   CLAIM_AUDIT has AFTER INSERT trigger CLAIMS.TR_AUDIT_FANOUT
--   CLAIM.SETTLED_TS is not generated; CLAIM_AUDIT.AUDIT_ID is IDENTITY
--   CLAIM_PAYMENT.CLAIM_ID has no enforced FK to CLAIM
--------------------------------------------------------------------------
CREATE PROCEDURE CLAIMS.SETTLE_CUSTOMER_CLAIMS
(
    IN  P_CUSTOMER_ID    BIGINT,
    IN  P_AS_OF_DATE     DATE,
    OUT P_DECISION       VARCHAR(30),
    OUT P_SETTLED_TOTAL  DECIMAL(15,2),
    OUT P_SETTLED_COUNT  INTEGER
)
LANGUAGE SQL
SPECIFIC SETTLE_CUSTOMER_CLAIMS_V2
VERSION V2
COMMIT ON RETURN NO
BEGIN
    DECLARE V_OPEN_COUNT    INTEGER       DEFAULT 0;
    DECLARE V_OPEN_TOTAL    DECIMAL(15,2) DEFAULT 0;
    DECLARE V_MAX_RISK      INTEGER       DEFAULT 0;
    DECLARE V_LAST_PAYMENT  DECIMAL(15,2) DEFAULT 0;
    DECLARE V_CLAIM_ID      BIGINT;
    DECLARE V_AMOUNT        DECIMAL(15,2);
    DECLARE V_PAID          DECIMAL(15,2);
    DECLARE V_NET           DECIMAL(15,2);
    DECLARE V_NOT_FOUND     SMALLINT      DEFAULT 0;
    DECLARE V_LOOP_DONE     SMALLINT      DEFAULT 0;
    DECLARE V_ERR_STATE     CHAR(5);

    DECLARE C_SETTLE CURSOR FOR
        SELECT C.CLAIM_ID,
               C.AMOUNT,
               COALESCE(P.PAID_TOTAL, 0)
          FROM CLAIM C
          LEFT JOIN (SELECT CLAIM_ID, SUM(AMOUNT) AS PAID_TOTAL
                       FROM CLAIM_PAYMENT
                      WHERE PAYMENT_DATE <= P_AS_OF_DATE
                      GROUP BY CLAIM_ID) P
            ON P.CLAIM_ID = C.CLAIM_ID
         WHERE C.CUSTOMER_ID = P_CUSTOMER_ID
           AND C.STATUS = 'APPROVED'
           AND C.CLAIM_ID NOT IN (SELECT CLAIM_ID
                                    FROM CLAIM_AUDIT
                                   WHERE ACTION_CODE = 'REVERSED')
         FOR READ ONLY;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET V_NOT_FOUND = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 V_ERR_STATE = RETURNED_SQLSTATE;
        SET P_DECISION = 'FAILED';
        ROLLBACK;
        RESIGNAL SQLSTATE '75002' SET MESSAGE_TEXT = 'Settlement aborted';
    END;

    SET P_DECISION      = 'STANDARD';
    SET P_SETTLED_TOTAL = 0;
    SET P_SETTLED_COUNT = 0;

    SELECT COUNT(*),
           COALESCE(SUM(AMOUNT), 0),
           COALESCE(MAX(RISK_SCORE), 0)
      INTO V_OPEN_COUNT, V_OPEN_TOTAL, V_MAX_RISK
      FROM CLAIM
     WHERE CUSTOMER_ID = P_CUSTOMER_ID
       AND STATUS IN ('PENDING', 'UNDER_REVIEW')
    HAVING COUNT(*) >= 3
        OR SUM(AMOUNT) > 25000;

    IF V_NOT_FOUND = 1 THEN
        SET V_OPEN_COUNT = 0;
        SET V_NOT_FOUND = 0;
    END IF;

    SELECT AMOUNT
      INTO V_LAST_PAYMENT
      FROM (SELECT AMOUNT,
                   ROW_NUMBER() OVER (ORDER BY PAYMENT_DATE DESC) AS RN
              FROM CLAIM_PAYMENT
             WHERE CLAIM_ID IN (SELECT CLAIM_ID
                                  FROM CLAIM
                                 WHERE CUSTOMER_ID = P_CUSTOMER_ID)) T
     WHERE RN = 1;

    IF EXISTS (SELECT 1
                 FROM CUSTOMER_HOLD
                WHERE CUSTOMER_ID = P_CUSTOMER_ID
                  AND ACTIVE_IND = 'Y'
                  AND (RELEASE_DATE IS NULL OR RELEASE_DATE > P_AS_OF_DATE)) THEN
        SET P_DECISION = 'BLOCKED';
        RETURN;
    END IF;

    IF V_MAX_RISK >= 900 THEN
        SET P_DECISION = 'RISK_REVIEW';
    ELSEIF V_OPEN_COUNT >= 3 OR V_OPEN_TOTAL > 25000 THEN
        SET P_DECISION = 'CAPACITY_REVIEW';
    END IF;

    OPEN C_SETTLE;
    settle_loop:
    WHILE V_LOOP_DONE = 0 DO
        FETCH C_SETTLE INTO V_CLAIM_ID, V_AMOUNT, V_PAID;
        IF V_NOT_FOUND = 1 THEN
            SET V_LOOP_DONE = 1;
            LEAVE settle_loop;
        END IF;

        SET V_NET = V_AMOUNT - V_PAID;
        IF V_NET <= 0 THEN
            ITERATE settle_loop;
        END IF;

        UPDATE CLAIM
           SET STATUS = 'SETTLED',
               SETTLED_TS = CURRENT TIMESTAMP
         WHERE CLAIM_ID = V_CLAIM_ID;

        INSERT INTO CLAIM_AUDIT (CLAIM_ID, ACTION_CODE, ACTION_TS, AMOUNT)
        VALUES (V_CLAIM_ID, 'SETTLED', CURRENT TIMESTAMP, V_NET);

        SET P_SETTLED_TOTAL = P_SETTLED_TOTAL + V_NET;
        SET P_SETTLED_COUNT = P_SETTLED_COUNT + 1;
    END WHILE;
    CLOSE C_SETTLE;

    MERGE INTO CUSTOMER_RISK T
    USING (SELECT P_CUSTOMER_ID AS CUSTOMER_ID,
                  V_MAX_RISK    AS RISK_SCORE
             FROM SYSIBM.SYSDUMMY1) S
       ON T.CUSTOMER_ID = S.CUSTOMER_ID
    WHEN MATCHED AND S.RISK_SCORE >= 900 THEN
        UPDATE SET RISK_LEVEL = 'CRITICAL', UPDATED_TS = CURRENT TIMESTAMP
    WHEN MATCHED THEN
        UPDATE SET RISK_LEVEL = 'STANDARD', UPDATED_TS = CURRENT TIMESTAMP
    WHEN NOT MATCHED THEN
        INSERT (CUSTOMER_ID, RISK_LEVEL, UPDATED_TS)
        VALUES (S.CUSTOMER_ID, 'STANDARD', CURRENT TIMESTAMP);

    IF P_SETTLED_COUNT > 0 THEN
        CALL CLAIMS.NOTIFY_SETTLEMENT(P_CUSTOMER_ID, P_SETTLED_COUNT);
        COMMIT;
    END IF;
END
